import { Injectable } from "@nestjs/common";
import { InjectRepository } from "@nestjs/typeorm";
import { type Repository } from "typeorm";
import { EntityRepository, type IUpdatableRepository } from "#/database/base/entity-repository.ts";
import { RolesEntity } from "#/modules/auth/schema/entities/roles.entity.ts";
import * as Roles from "#/modules/auth/schema/types/roles/index.ts";

/**
 * Repository of Roles: the base repository configured with the entity's
 * generated query fields. Regenerated by Dryv; the feature repositories build the contract's
 * named queries on top of it.
 */
@Injectable()
export class RolesRepository
  extends EntityRepository<
    RolesEntity,
    Roles.Types.RolesSortableField,
    Roles.Types.RolesEditableField,
    Roles.Types.RolesSelectableField,
    Roles.Types.IRolesCreatable
  >
  implements IUpdatableRepository<RolesEntity, Roles.Types.IRolesUpdatable>
{
  constructor(
    @InjectRepository(RolesEntity)
    repository: Repository<RolesEntity>,
  ) {
    super(repository, Roles.Config.ROLES_QUERY_OPTIONS);
  }

  /** Updates a row from only the editable fields of `data`. */
  async updateEditable(id: string, data: Roles.Types.IRolesUpdatable): Promise<RolesEntity | null> {
    const stamped = await this.stampUpdate(id, data);
    return stamped === null ? null : await this.update(id, stamped);
  }

  /** Find the roles with this code (unique). */
  async findByCode(code: NonNullable<RolesEntity["code"]>): Promise<RolesEntity | null> {
    return await this.findOne({ code });
  }
}
